EVENTS = [
    dict(id="fall-of-babylon-641", title="Amr ibn al-As takes Babylon", periodId="fustat-700", date="April 641", kind="civic",
         at=dict(landmarkId="babylon-fortress"), effect="crowd",
         text="After a siege of seven months the Byzantine garrison of Babylon surrendered to Amr's army of a few thousand Arabs, who had crossed the Sinai at the end of 639. The fall of the fortress opened the Delta; Alexandria followed in 642. The Arabs camped round its walls, and the camp (fustat) became Egypt's new capital.",
         sourceIds=["butler-conquest", "wiki-babylon-fortress", "wiki-fustat"]),
    dict(id="founding-fustat-642", title="The first mosque of Fustat", periodId="fustat-700", date="641–642", kind="construction",
         at=dict(landmarkId="mosque-of-amr"), effect="construction",
         text="Amr laid out the tribes' plots round a small mosque of mud brick with palm-trunk columns and a palm-leaf roof. Tradition says eighty Companions of the Prophet stood to fix its prayer direction. The camp, the fustat, became one of the great cities of the Islamic world, and its mosque was rebuilt, enlarged and loved for a millennium.",
         sourceIds=["wiki-amr", "kubiak-fustat"]),
    dict(id="canal-reopened-642", title="Grain boats for Medina", periodId="fustat-700", date="641–643", kind="construction",
         at=dict(spotId="canal-landing"), effect="construction",
         text="The caliph Umar, facing famine in Arabia, ordered Amr to reopen the old canal from the Nile to the Red Sea. Within months Egyptian peasants had cleared it, and grain boats sailed from Fustat to Qulzum, where the cargo was shipped on to the Hijaz. The canal ran for more than a century.",
         sourceIds=["wiki-khalij", "butler-conquest"]),
    dict(id="ibn-tulun-mosque-879", title="Ibn Tulun's mosque is finished", periodId="tulunid-880", date="879", kind="construction",
         at=dict(landmarkId="ibn-tulun"), effect="construction",
         text="On Jabal Yashkur the governor's builders completed a mosque big enough for his whole army, in brick so that, Ibn Tulun is said to have explained, fire and flood could not destroy it. Its foundation slab is dated 879. A later story claims its spiral minaret copied a paper strip the ruler twisted absent-mindedly round his finger.",
         sourceIds=["wiki-ibn-tulun", "maqrizi-khitat"]),
    dict(id="sack-of-qatai-905", title="The Abbasids raze al-Qata'i", periodId="tulunid-880", date="January 905", kind="disaster",
         at=dict(landmarkId="tulunid-palace"), effect="fire",
         text="An Abbasid army under Muhammad ibn Sulayman ended the Tulunid dynasty, plundered al-Qata'i and burned and pulled down its palaces. Only the great mosque was spared. For decades the ruined quarter was a wasteland of broken walls between Fustat and the Muqattam.",
         sourceIds=["wiki-al-qatai", "maqrizi-khitat"]),
    dict(id="founding-qahira-969", title="Jawhar lays out al-Qahira", periodId="fatimid-1050", date="July 969", kind="construction",
         at=dict(landmarkId="eastern-palace"), effect="construction",
         text="The Fatimid general Jawhar al-Siqilli took Egypt for the caliph al-Mu'izz and, the night his army arrived, marked out a walled city north of Fustat with a palace at its centre. A later legend says astrologers strung bells on ropes to signal the lucky moment, and a raven set them off early, while Mars, al-Qahir, was rising.",
         sourceIds=["wiki-jawhar", "maqrizi-khitat"]),
    dict(id="hakim-vanishes-1021", title="The caliph al-Hakim vanishes", periodId="fatimid-1050", date="February 1021", kind="civic",
         at=dict(latlon=(30.0200, 31.2690)), effect="none",
         text="Al-Hakim, the unpredictable caliph who had banned some foods, destroyed churches and founded the House of Knowledge, liked to ride alone at night on the Muqattam. One night he did not return; his donkey and bloodstained clothes were found. He was probably murdered; the Druze believe he went into occultation.",
         sourceIds=["wiki-al-hakim-caliph", "maqrizi-khitat"]),
    dict(id="canal-opening-1047", title="The caliph cuts the canal dam", periodId="fatimid-1050", date="August 1047", kind="festival",
         at=dict(latlon=(30.0262, 31.2366)), effect="procession",
         text="Nasir-i Khusraw watched the festival of the flood: when the Nile reached sixteen cubits, the caliph rode from the palace in a procession of thousands, with gilded saddles and a tent of brocade, to the canal mouth. He threw a spear at the earthen dam, workmen broke it, and the water rushed into the Khalij amid cheering crowds and boats.",
         sourceIds=["nasir-khusraw", "wiki-wafa-al-nil"]),
    dict(id="burning-of-fustat-1168", title="Fustat burns", periodId="fatimid-1050", date="November 1168", kind="disaster",
         at=dict(latlon=(30.0150, 31.2400)), effect="fire",
         text="With the crusader army of King Amalric of Jerusalem approaching, the vizier Shawar ordered Fustat evacuated and set alight so the Franks could not use it. Chroniclers say it burned for fifty-four days, set alight with twenty thousand pots of naphtha; archaeologists think the damage was less complete than they claim. Fustat never fully recovered, and al-Qahira became Cairo's heart.",
         sourceIds=["wiki-fustat", "maqrizi-khitat"]),
    dict(id="citadel-begun-1176", title="Saladin begins the Citadel", periodId="mamluk-1350", date="1176", kind="construction",
         at=dict(landmarkId="citadel"), effect="construction",
         text="Saladin, who had ended the Fatimid caliphate in 1171, chose the Muqattam spur for a fortress, and his eunuch emir Qaraqush built it with stone from the small pyramids of Giza and with crusader prisoners as labour. Saladin never lived in it; his nephew al-Kamil moved in in 1207.",
         sourceIds=["wiki-citadel", "maqrizi-khitat"]),
    dict(id="qalawun-1285", title="Qalawun's hospital in thirteen months", periodId="mamluk-1350", date="1284–1285", kind="construction",
         at=dict(landmarkId="qalawun"), effect="construction",
         text="Sultan Qalawun, who it is said had been cured as a young amir in Nur al-Din's hospital at Damascus, built his own on the site of the Fatimid Western Palace. Al-Maqrizi says the work was done in about thirteen months, with passers-by, even notables, forced to carry stones. The hospital served Cairo for six hundred years.",
         sourceIds=["wiki-qalawun", "maqrizi-khitat"]),
    dict(id="black-death-1348", title="The Great Plague reaches Cairo", periodId="mamluk-1350", date="autumn 1348", kind="disaster",
         at=dict(latlon=(30.0480, 31.2595)), effect="crowd",
         text="The plague came by sea to Alexandria and up the Nile. At its height, in the winter of 1348–1349, chroniclers counted thousands of funerals a day; biers ran short and the dead were carried on planks and doors. Perhaps a third of the city died. Markets stood empty and fields untilled.",
         sourceIds=["dols-black-death", "maqrizi-khitat", "wiki-black-death"]),
    dict(id="sultan-hasan-minaret-1361", title="A minaret falls at Sultan Hasan's mosque", periodId="mamluk-1350", date="1361", kind="disaster",
         at=dict(landmarkId="sultan-hasan"), effect="crowd",
         text="Sultan Hasan's enormous mosque, paid for partly from the estates of plague victims, was still unfinished when one of the minarets over its portal collapsed, killing about three hundred people. People took it as an omen; weeks later the sultan was murdered by his own Mamluks, and the portal minarets were never rebuilt.",
         sourceIds=["wiki-sultan-hasan", "maqrizi-khitat"]),
    dict(id="ottoman-conquest-1517", title="Tuman Bay hanged at Bab Zuwayla", periodId="ottoman-1600", date="15 April 1517", kind="civic",
         at=dict(landmarkId="bab-zuwayla"), effect="crowd",
         text="Selim I's Ottoman army beat the Mamluks at Raydaniyya, north of Cairo, in January 1517 and took the city after days of street fighting. The last sultan, Tuman Bay, was caught and hanged in the gateway of Bab Zuwayla before the crowd. Egypt became an Ottoman province for three centuries.",
         sourceIds=["wiki-tuman-bay", "wiki-ottoman-mamluk-war", "wiki-bab-zuwayla"]),
    dict(id="coffee-quarrel-1530s", title="Preachers against coffee", periodId="ottoman-1600", date="1530s", kind="riot",
         at=dict(spotId="coffee-house"), effect="crowd",
         text="Coffee divided Cairo's scholars: some jurists called it an intoxicant and the coffee house a den of idleness. In the 1530s, after sermons against it, crowds are reported to have attacked coffee houses and their customers. The authorities found no grounds to ban it, and the coffee houses multiplied.",
         sourceIds=["hattox-coffee", "wiki-coffeehouse"]),
    dict(id="mahmal-1600", title="The Mahmal leaves for Mecca", periodId="ottoman-1600", date="every year in Shawwal", kind="procession",
         at=dict(landmarkId="citadel"), effect="procession",
         text="Each year the pilgrim caravan formed below the Citadel round the Mahmal, an empty, richly covered litter on a camel, the symbol of the ruler's protection of the pilgrimage, with the new cloth for the Ka'ba. Drummers, soldiers and Sufis with banners led it through the city and out of Bab al-Nasr.",
         sourceIds=["wiki-mahmal", "lane-egyptians"]),
]

